  streaming_setup_discord: 'Discord アプリを作成し（開発者ポータル）、OAuth2 にリダイレクト http://localhost を追加して、Client ID と Client Secret をここに貼り付けてください。Discord デスクトップ クライアントが起動している必要があります。',
