  streaming_discord_pipedenied: 'Discord が管理者として実行されているため、Xenon から通信できません。Discord を完全に終了し（トレイアイコン → 終了）、通常どおり起動し直してから「接続」を押してください。待っても解決しません。',
  streaming_discord_closed: 'Discord が接続を閉じました。クライアント ID が正しいこと、そしてこのアプリケーションを作成したアカウントで Discord デスクトップ アプリにサインインしていることを確認してください。',
  streaming_discord_denied: 'Discord で認証が拒否されました。リクエストを承認し、このアプリケーションを所有するアカウントでサインインしていることを確認してください。',
  streaming_discord_timeout: '認証ウィンドウがタイムアウトしました。もう一度試して、Discord で「認証」を素早くクリックしてください。',
  streaming_token_failed: 'コードの交換中にログインに失敗しました。クライアント シークレットと、リダイレクト URL が正確に http://localhost であることを確認してください。',
  streaming_discord_inflight: 'すでに承認待ちのログインがあります。Discord のポップアップを確認するか、タイムアウトするまで待ってから再試行してください。',
  streaming_discord_badclientid: 'Discord が Client ID を拒否しました。開発者ポータルでアプリの General Information ページにある「Application ID」をコピーし、「認証情報を編集」から入力し直してください。',
  streaming_discord_authfailed: 'Discord が認証を拒否しました。Discord デスクトップ アプリは、開発者ポータルでこのアプリケーションを所有しているアカウントと同じアカウントでサインインしている必要があります。',
  streaming_discord_invalidscope: 'Discord が要求された権限を拒否しました。ここで必要な「rpc」アクセスは、このアプリケーションを所有するアカウント（またはアプリの OAuth2 テスターに追加したアカウント）にのみ付与されます。Discord デスクトップ アプリがどのアカウントでサインインしているか確認してください。アプリが Activity（「Embedded App」フラグ）の場合も Discord は拒否します。このエラーにリダイレクトは関係ありません。',
  streaming_discord_badsecret: 'Discord が Client Secret を拒否しました。開発者ポータルでアプリを開いてシークレットをリセットし、新しい値を「認証情報を編集」に貼り付けてください。',
  streaming_discord_network: 'Discord は認証しましたが、この PC が discord.com に接続できずログインを完了できませんでした。VPN、ファイアウォール、プロキシの設定を確認して、もう一度「接続」を押してください。',
  streaming_discord_id_shape: 'これは Discord の Client ID ではないようです。アプリの General Information ページに「Application ID」と表示されている長い数字です（Public Key や Client Secret ではありません）。',
